// --- Batch conversion ---

func batchToProto(b *domain.BatchRecord) *pb.BatchRecord {
	if b == nil {
		return nil
	}
	out := &pb.BatchRecord{
		Id:                b.ID,
		TenantId:          b.TenantID,
		RecordId:          b.RecordID,
		BatchNumber:       b.BatchNumber,
		Quantity:          b.Quantity,
		Unit:              b.Unit,
		ProductionDate:    timePtrToTs(b.ProductionDate),
		ExpiryDate:        timePtrToTs(b.ExpiryDate),
		StorageConditions: b.StorageConditions,
		QualityGrade:      b.QualityGrade,
		Metadata:          metadataJSONToMap(b.Metadata),
		CreatedAt:         timeToTs(b.CreatedAt),
		UpdatedAt:         timeToTs(b.UpdatedAt),
		Version:           b.Version,
		WeightKg:          b.WeightKg,
	}
	if b.CropCycleID != nil {
		out.CropCycleId = *b.CropCycleID
	}
	if b.YieldRecordID != nil {
		out.YieldRecordId = *b.YieldRecordID
	}
	return out
}

